cd opt; tail -202 xtbopt.log | sed 's/^ energy.*/frame/' > cur.xyz; head -3 cur.xyz; python -c "
import numpy as np
L=open('cur.xyz').read().split('\n')[2:202]
S=[l.split()[0] for l in L]; P=np.array([[float(x) for x in l.split()[1:4]] for l in L])
idx={s:[i for i,x in enumerate(S) if x==s] for s in ['Au','Cu']}
print(idx)
for a in idx['Au']:
    for c in [0,1]: print('Au',a,'C',c,np.linalg.norm(P[a]-P[c]))
for c in [0,1]: print('Cu-C',c,np.linalg.norm(P[idx['Cu'][0]]-P[c]))
print('C0-C1',np.linalg.norm(P[0]-P[1]))
print('Au-Au',np.linalg.norm(P[2]-P[32]))
def ang(a,b,c):
    v1=P[a]-P[b];v2=P[c]-P[b];return np.degrees(np.arccos(v1@v2/np.linalg.norm(v1)/np.linalg.norm(v2)))
print('C3-Au2-C0',ang(3,2,0),'C33-Au32-C1',ang(33,32,1),'C0-C1-Au32',ang(0,1,32),'C1-C0-Au2',ang(1,0,2))
"
